-- ============================================================
-- 潮汐商城（Flash Mall）商品数据种子脚本
-- 说明: 仅包含商品相关数据 —— 分类(category) / SPU(spu) / SKU(sku)
--       用户、地址、优惠券、购物车等用户相关数据不在本脚本内
-- 前提: 先执行 mall.sql 建库建表，再执行本脚本
-- 图片: 网上图片占位服务 picsum.photos（免费真实照片，seed 固定 = 同一张图）
--       如需本地图片，可改用 /img/products/pXX.svg（仓库内已备好 SVG 占位图）
-- ============================================================

USE flash_mall;

-- 清空商品相关表（可重复执行；不影响订单/用户数据）
-- 同时重置自增计数，避免与脚本里的显式 id 冲突
SET FOREIGN_KEY_CHECKS=0;
DELETE FROM `sku`;
DELETE FROM `spu`;
DELETE FROM `category`;
ALTER TABLE `sku`      AUTO_INCREMENT = 1;
ALTER TABLE `spu`      AUTO_INCREMENT = 1;
ALTER TABLE `category` AUTO_INCREMENT = 1;
SET FOREIGN_KEY_CHECKS=1;

